FORMAT = "mrc-daily-stock-summary/1"
TITLE = "Daily Stock Summary"
VERIFIED, UNVERIFIED = "VERIFIED", "UNVERIFIED"
# Alert section status
CURRENT, STORED, UNAVAILABLE = "CURRENT", "STORED_NOT_RECHECKED", "UNAVAILABLE"
MAX_ALERT_ITEMS = alerts.MAX_LOADED_ALERTS
MAX_CHANGE_ITEMS = 2000
MAX_FAILURES = 50
PREVIEW_ITEMS = 200            # rows per list in the on-screen preview; the saved files hold every loaded row
ROLE_NAMES = {"stock": "Storage", "bom": "BOM"}
CHANGE_TYPES = ("QUANTITY_CHANGED", "ADDED", "REMOVED", "VALIDITY_CHANGED", "DUPLICATE_CHANGED")
OBSERVED_NOT_CONSUMPTION = "Observed Change ≠ Actual Consumption"
NOT_STOCK_NORMAL = ("Nothing in this report states that stock is normal or sufficient: alerts follow the M3.2C rules "
                    "only, thresholds and units are pending business confirmation, and unavailable alerts are not "
                    "'no alerts'.")
SUM_NOTE = ("One material can have several alert types: the per-type counts must not be added up as a number of "
            "materials. The same Material ID in different Storage Sheets is one ID here; each Sheet entry is listed.")
NO_RECORD_NOTE = ("No observed change was recorded for this date. This only means that nothing was recorded: Storage "
                  "may not have been synchronised, or the file did not change between synchronisations. It does not "
                  "mean the warehouse had no movement.")
STATUS_TEXT = {"VALID": "VALID", "BLANK": "BLANK — not 0", "INVALID": "INVALID — not converted"}


class DailyError(Exception):
    """The summary cannot be generated or saved; nothing was written."""


class DailyReadError(DailyError):
    """The database could not be read; no summary (or no saved file) results from this attempt."""


class DailyStale(DailyError):
    """The data or this session's verification changed after generation; generate the summary again."""


class DailyUnsupported(DailyError):
    """Saving is refused: the database's journal mode is outside the supported publication-locking contract."""


class ConfirmationRequired(DailyError):
    """The summary would be UNVERIFIED and the user has not confirmed generating an UNVERIFIED report."""

    def __init__(self, reasons):
        self.reasons = tuple(reasons)
        super().__init__("This summary cannot be verified: " + "; ".join(self.reasons))


@dataclass(frozen=True)
class Session:
    """What the application's session had verified when the request was made (captured on the Tk thread)."""
    generation: int | None                      # alert SessionGate generation of the request
    authorization: alerts.Authorization | None  # both files verified by this session, or None
    alert_current: bool                         # a verified evaluation of this generation was confirmed
    reason: str | None = None                   # why it is not verified, as the application states it


@dataclass(frozen=True)
class DailySummary:
    """Immutable: every rendering is produced from json_text."""
    report_id: str
    report_date: str
    verified: bool
    generation: int | None
    basis: tuple                 # database state the summary was read from; save() requires it unchanged
    generated_local: str         # YYYYMMDD_HHMMSS, for file names
    json_text: str

    def data(self) -> dict:
        return json.loads(self.json_text)

    @property
    def digest(self) -> str:
        return hashlib.sha256(self.json_text.encode("utf-8")).hexdigest()

    @property
    def status(self) -> str:
        return VERIFIED if self.verified else UNVERIFIED


# ---------------------------------------------------------------------- day window
def local_moment(moment: datetime, tz=None) -> datetime:
    return moment.astimezone(tz) if tz is not None else moment.astimezone()


def _local_midnight(day: date, tz=None) -> datetime:
    naive = datetime(day.year, day.month, day.day)
    return naive.astimezone() if tz is None else naive.replace(tzinfo=tz)


def _offset(moment: datetime) -> str:
    seconds = int(moment.utcoffset().total_seconds())
    sign = "+" if seconds >= 0 else "-"
    return f"UTC{sign}{abs(seconds) // 3600:02d}:{abs(seconds) % 3600 // 60:02d}"


def day_window(day: date, tz=None) -> dict:
    """The local calendar day as a UTC query window: start inclusive, next day's start exclusive."""
    start, end = _local_midnight(day, tz), _local_midnight(day + timedelta(days=1), tz)
    return dict(start_local=start.isoformat(), end_local=end.isoformat(), start_utc=stamp(start), end_utc=stamp(end),
                hours=(end.astimezone(timezone.utc) - start.astimezone(timezone.utc)).total_seconds() / 3600,
                rule="Local day start inclusive, next local day start exclusive; times converted to UTC.")


def timezone_label(moment: datetime) -> str:
    name, offset = moment.tzname(), _offset(moment)
    return offset if not name or name == offset else f"{name} ({offset})"


# ---------------------------------------------------------------------- value text (no Tk)
def raw_text(pair, status=None) -> str:
    """A stored [kind, text] value exactly as read; blank shown as (blank), never as 0."""
    if pair is None:
        return "—"
    value = decode(*pair)
    if value is None or (isinstance(value, str) and not value.strip()):
        text = "(blank)"
    else:
        text = display(value)
    return text if status in (None, "VALID") else f"{text} ({STATUS_TEXT.get(status, status)})"


def side_text(status, raw) -> str:
    """One side of an observed change, exactly as recorded."""
    if status is None:
        return "absent"
    if status == "DUPLICATE":
        return "DUPLICATE: " + " | ".join("(blank)" if v is None else display(v) for v in raw)
    value = raw[0] if raw else None
    text = "(blank)" if status == "BLANK" or value is None else display(value)
    return text if status == "VALID" else f"{text} ({STATUS_TEXT.get(status, status)})"


def signed(text) -> str:
    try:
        value = Decimal(text)
    except (InvalidOperation, TypeError):
        return str(text)
    return ("+" if value > 0 else "") + display(value)


# ---------------------------------------------------------------------- reading (one consistent view)
def _version(row) -> dict | None:
    if row is None:
        return None
    return dict(id=row["id"], file_name=row["file_name"], path=row["source_path"], imported_utc=row["imported_at"],
                source_modified_utc=row["source_modified_at"], size_bytes=row["size_bytes"],
                file_sha256=row["file_sha256"], sheet_count=row["sheet_count"], record_count=row["record_count"])


def _run(row) -> dict | None:
    if row is None:
        return None
    return dict(id=row["id"], outcome=row["outcome"], trigger=row["trigger"], path=row["source_path"],
                finished_utc=row["finished_at"], version_id=row["source_version_id"], error=row["error_message"])


def _latest_runs(conn) -> dict:
    return {role: conn.execute("SELECT * FROM sync_runs WHERE role = ? ORDER BY id DESC LIMIT 1", (role,)).fetchone()
            for role in ("stock", "bom")}


def _basis(conn) -> tuple:
    """The database state a summary depends on. Any newer version, sync record or evaluation changes it."""
    schema = schema_version(conn)
    stock, bom = current_version(conn, "stock"), current_version(conn, "bom")
    runs = _latest_runs(conn)
    evaluation = None
    if schema >= ALERT_SCHEMA_VERSION:
        row = conn.execute("SELECT max(id) FROM alert_evaluations").fetchone()
        evaluation = row[0]
    return (schema, stock["id"] if stock else None, bom["id"] if bom else None,
            runs["stock"]["id"] if runs["stock"] else None, runs["bom"]["id"] if runs["bom"] else None, evaluation)


def read_basis(database) -> tuple:
    try:
        with read_view(database) as conn:
            return _basis(conn)
    except HistoryReadError as exc:
        raise DailyReadError(f"The local database could not be read: {exc}") from exc


def _sources(conn, window, session) -> dict:
    start, end = window["start_utc"], window["end_utc"]
    states = freshness(conn)
    result = {}
    for role in ("stock", "bom"):
        current = current_version(conn, role)
        latest = conn.execute("SELECT * FROM sync_runs WHERE role = ? ORDER BY id DESC LIMIT 1", (role,)).fetchone()
        success = conn.execute("SELECT * FROM sync_runs WHERE role = ? AND outcome IN (?, ?) ORDER BY id DESC LIMIT 1",
                               (role, IMPORTED, UNCHANGED)).fetchone()
        at_day_end = conn.execute("SELECT * FROM source_versions WHERE role = ? AND imported_at < ? ORDER BY id DESC"
                                  " LIMIT 1", (role, end)).fetchone()
        imported = []
        for v in conn.execute("SELECT * FROM source_versions WHERE role = ? AND imported_at >= ? AND imported_at < ?"
                              " ORDER BY id", (role, start, end)).fetchall():
            before = conn.execute("SELECT source_path FROM source_versions WHERE role = ? AND id < ? ORDER BY id DESC"
                                  " LIMIT 1", (role, v["id"])).fetchone()
            item = _version(v)
            item["previous_path"] = before[0] if before else None
            item["source_switched"] = before is not None and source_identity(before[0]) != source_identity(v["source_path"])
            imported.append(item)
        outcomes = {r[0]: r[1] for r in conn.execute(
            "SELECT outcome, count(*) FROM sync_runs WHERE role = ? AND finished_at >= ? AND finished_at < ?"
            " GROUP BY outcome", (role, start, end))}
        failures = [_run(r) for r in conn.execute(
            "SELECT * FROM sync_runs WHERE role = ? AND finished_at >= ? AND finished_at < ? AND outcome NOT IN (?, ?)"
            " ORDER BY id LIMIT ?", (role, start, end, IMPORTED, UNCHANGED, MAX_FAILURES))]
        granted = session.authorization.source(role) if session.authorization is not None else None
        state = states[role]
        result[role] = dict(
            role=ROLE_NAMES[role], current=_version(current), in_effect_at_day_end=_version(at_day_end),
            imported_on_day=imported, latest_run=_run(latest), last_success=_run(success),
            freshness_state=state.label, runs_on_day={k: outcomes.get(k, 0) for k in (IMPORTED, UNCHANGED, "UNAVAILABLE",
                                                                                        "FAILED")},
            failures_on_day=failures, failures_on_day_total=sum(outcomes.get(k, 0) for k in ("UNAVAILABLE", "FAILED")),
            session_verified=dict(version_id=granted[0], path=granted[1]) if granted else None)
    return result


def _version_checks(conn, session) -> list[str]:
    """Reasons why the database's current versions are not the ones this session verified."""
    reasons = []
    auth = session.authorization
    runs = _latest_runs(conn)
    for role in ("stock", "bom"):
        name = ROLE_NAMES[role]
        current, run = current_version(conn, role), runs[role]
        if current is None:
            reasons.append(f"{name} has not been synchronised")
            continue
        if run is None or run["outcome"] not in (IMPORTED, UNCHANGED) or run["source_version_id"] != current["id"]:
            reasons.append(f"the newest {name} synchronisation is not a success for the current version "
                           f"(v{current['id']})")
        if auth is None:
            continue
        granted = auth.source(role)
        if granted is None or granted[0] != current["id"]:
            reasons.append(f"this session verified {name} v{granted[0] if granted else '—'}, but the current "
                           f"{name} version in the database is v{current['id']}")
        elif run is None or not same_path(granted[1], run["source_path"]):
            reasons.append(f"the newest {name} synchronisation is not of the file this session verified")
    return reasons


def _alerts(conn) -> dict:
    """Stored alerts of the current files and whether they belong to exactly the current versions."""
    schema = schema_version(conn)
    if schema < ALERT_SCHEMA_VERSION:
        return dict(match=False, reason=f"stock alerts need the upgraded local database (schema {schema} → "
                                        f"{ALERT_SCHEMA_VERSION}); the summary never upgrades it", schema=schema)
    state = alerts.state_in(conn, include_resolved=False, include_other_sources=False, limit=MAX_ALERT_ITEMS)
    stock, bom = current_version(conn, "stock"), current_version(conn, "bom")
    done = state.latest_completed
    base = dict(schema=schema, other_source_active=state.other_sources_active,
                latest_attempt=_evaluation_brief(state.latest), evaluation=_evaluation_brief(done))
    if stock is None or bom is None:
        return dict(base, match=False, reason="Storage and BOM must both be synchronised before alerts exist")
    if done is None:
        return dict(base, match=False, reason="no verified (COMPLETED) alert evaluation of the current files exists")
    if (done["stock_version_id"], done["bom_version_id"]) != (stock["id"], bom["id"]):
        return dict(base, match=False, reason=(
            f"the last verified alert evaluation #{done['id']} is of Storage v{done['stock_version_id']} / BOM "
            f"v{done['bom_version_id']}, but the current versions are Storage v{stock['id']} / BOM v{bom['id']}: "
            "its alerts are not shown as current"))
    scope = (state.storage_source, state.bom_source)
    in_scope = "status = 'ACTIVE' AND " + alerts._in_scope_sql()
    foreign = conn.execute(f"SELECT count(*) FROM stock_alerts WHERE {in_scope} AND last_evaluation_id <> ?",
                           (*scope, done["id"])).fetchone()[0]
    if foreign:
        return dict(base, match=False, reason=f"{foreign} active alerts of these files were not confirmed by evaluation "
                                              f"#{done['id']}; the stored alerts are inconsistent and not shown")
    by_type = []
    for alert_type in alerts.TYPES:
        count, distinct, without, sheets = conn.execute(
            f"SELECT count(*), count(DISTINCT material_key), sum(material_key IS NULL), count(DISTINCT stock_sheet)"
            f" FROM stock_alerts WHERE {in_scope} AND alert_type = ?", (*scope, alert_type)).fetchone()
        subtypes = {r[0]: r[1] for r in conn.execute(
            f"SELECT subtype, count(*) FROM stock_alerts WHERE {in_scope} AND alert_type = ? GROUP BY subtype"
            f" ORDER BY subtype", (*scope, alert_type))} if alert_type == alerts.DATA_ISSUE else {}
        by_type.append(dict(type=alert_type, alerts=count, distinct_material_ids=distinct,
                            entries_without_material_id=without or 0, storage_sheets=sheets, subtypes=subtypes))
    distinct_any = conn.execute(f"SELECT count(DISTINCT material_key) FROM stock_alerts WHERE {in_scope}",
                                scope).fetchone()[0]
    summary = done["summary"]
    return dict(base, match=True, reason=None, by_type=by_type, distinct_material_ids_any_type=distinct_any,
                total=state.total_rows, items=[_alert_item(r) for r in state.rows],
                truncated=state.total_rows > len(state.rows),
                scope=dict(storage_file=stock["source_path"], storage_version=stock["id"],
                           bom_file=bom["source_path"], bom_version=bom["id"], sheets=done["sheet_scope"],
                           evaluation_id=done["id"], evaluated_utc=done["finished_at"]),
                sheets=summary.get("sheets", {}),
                bom=dict(rows=summary.get("bom_rows"), products=summary.get("bom_products"),
                         distinct_ids=summary.get("bom_distinct_ids"),
                         rows_without_usable_id=summary.get("bom_rows_without_usable_id")))


def _evaluation_brief(e) -> dict | None:
    if e is None:
        return None
    counts = {t: 0 for t in alerts.TYPES}
    for info in (e.get("summary") or {}).get("sheets", {}).values():
        for t, n in info.get("counts", {}).items():
            counts[t] = counts.get(t, 0) + n
    return dict(id=e["id"], trigger=e["trigger"], outcome=e["outcome"], finished_utc=e["finished_at"],
                stock_version_id=e["stock_version_id"], bom_version_id=e["bom_version_id"],
                reason=e.get("error_message"), counts_by_type=counts if e.get("summary") else None)


def _evaluations_on_day(conn, window) -> list[dict]:
    if schema_version(conn) < ALERT_SCHEMA_VERSION:
        return []
    rows = conn.execute("SELECT * FROM alert_evaluations WHERE finished_at >= ? AND finished_at < ? ORDER BY id",
                        (window["start_utc"], window["end_utc"])).fetchall()
    return [_evaluation_brief(alerts._evaluation(r)) for r in rows]


def _alert_item(r) -> dict:
    d = r.detail
    item = dict(type=r.alert_type, issue=r.subtype if r.alert_type == alerts.DATA_ISSUE else None, sheet=r.stock_sheet,
                material_id=r.material_key, storage_file=d.get("storage_file"), storage_version=r.stock_version_id,
                first_seen_utc=r.first_seen_at, last_seen_utc=r.last_seen_at, note=d.get("note", ""))
    if r.alert_type == alerts.NOT_IN_MASTER:
        occurrences = d.get("occurrences", [])
        item.update(rows=None, description=raw_text(occurrences[0]["description"]) if occurrences else "—",
                    stock="unknown — not in stock master (not 0)", threshold="—", shortfall=None,
                    bom_file=d.get("bom_file"), bom_version=r.bom_version_id, bom_rows=d.get("bom_rows"),
                    products=d.get("products", []),
                    used_in=[dict(product=o["product"], bom_sheet=o["bom_sheet"], row=o["row"], qty=raw_text(o["qty"]))
                             for o in occurrences])
    elif "rows" in d:  # duplicate Storage ID: every row separately, never added
        item.update(rows=[x["row"] for x in d["rows"]], description=raw_text(d["rows"][0]["description"]),
                    stock=" | ".join(raw_text(x["stock"], x["stock_status"]) for x in d["rows"]),
                    threshold=(" | ".join(raw_text(x["threshold"]) for x in d["rows"])
                               if d["rows"][0].get("threshold") else "—"), shortfall=None)
    elif isinstance(d.get("threshold"), dict):  # ambiguous threshold columns of a Sheet
        item.update(rows=None, description="—", stock="—", shortfall=None,
                    threshold="several columns: " + ", ".join(f"{c} '{h}'" for c, h in d["threshold"].get("candidates", [])))
    else:
        item.update(rows=[d.get("row")], description=raw_text(d.get("description")),
                    stock=raw_text(d.get("stock"), d.get("stock_status")),
                    threshold=((raw_text(d["threshold"], d.get("threshold_status")) +
                                f" [{d.get('threshold_column')} '{d.get('threshold_header')}']") if d.get("threshold")
                               else "—"),
                    shortfall=d.get("threshold_shortfall"), rack=raw_text(d.get("rack")), level=raw_text(d.get("level")))
        if r.material_key is None:
            item["code"] = raw_text(d.get("code"))
    return item


def _changes(conn, window) -> dict:
    start, end = window["start_utc"], window["end_utc"]
    joins = (" FROM inventory_changes c JOIN inventory_snapshots s ON s.id = c.snapshot_id"
             " JOIN source_versions av ON av.id = s.source_version_id"
             " LEFT JOIN source_versions pv ON pv.id = s.previous_version_id"
             " WHERE s.observed_at >= ? AND s.observed_at < ?")
    args = (start, end)
    by_type = {t: dict(changes=0, distinct_material_ids=0) for t in CHANGE_TYPES}
    for kind, count, distinct in conn.execute("SELECT c.change_type, count(*), count(DISTINCT c.material_key)" + joins +
                                              " GROUP BY c.change_type", args):
        by_type[kind] = dict(changes=count, distinct_material_ids=distinct)
    total, distinct = conn.execute("SELECT count(*), count(DISTINCT c.material_key)" + joins, args).fetchone()
    items = []
    for r in conn.execute("SELECT c.*, s.observed_at, s.same_source_path, pv.imported_at AS before_at,"
                          " pv.source_path AS before_path, av.source_path AS after_path" + joins +
                          " ORDER BY s.observed_at, s.id, c.sheet_name, c.material_key, c.id LIMIT ?",
                          (*args, MAX_CHANGE_ITEMS)):
        c = _change(r)
        if c.difference is not None:
            difference, reason = signed(c.difference), None
        elif c.change_type == "QUANTITY_CHANGED":
            difference, reason = None, "not comparable: the source file switched between these versions"
        else:
            difference, reason = None, "not calculated for this change type (no two single valid records)"
        items.append(dict(observed_utc=c.after_at, sheet=c.sheet, material_id=r["material_key"],
                          change_type=c.change_type, before_utc=c.before_at, before=side_text(c.before_status, c.before_raw),
                          after=side_text(c.after_status, c.after_raw), observed_difference=difference,
                          difference_reason=reason, source_switched=c.source_switched, before_file=c.before_path,
                          after_file=c.after_path, note=c.note))
    snapshots = []
    for s in conn.execute("SELECT s.*, v.source_path, v.file_name FROM inventory_snapshots s JOIN source_versions v"
                          " ON v.id = s.source_version_id WHERE s.observed_at >= ? AND s.observed_at < ? ORDER BY"
                          " s.observed_at, s.id", args):
        snapshots.append(dict(
            observed_utc=s["observed_at"], version_id=s["source_version_id"], file=s["source_path"],
            previous_version_id=s["previous_version_id"], baseline=s["previous_version_id"] is None,
            source_switched=s["same_source_path"] == 0, source_modified_utc=s["source_modified_at"],
            counts=dict(quantity_changed=s["quantity_changed_count"], added=s["added_count"],
                        removed=s["removed_count"], validity_changed=s["validity_changed_count"],
                        duplicate_changed=s["duplicate_changed_count"])))
    return dict(caveat=OBSERVED_NOT_CONSUMPTION, detail=OBSERVED_CHANGE_CAVEAT, by_type=by_type, total=total,
                distinct_material_ids=distinct, items=items, truncated=total > len(items), snapshots=snapshots)


def _limitations(conn, window) -> dict:
    start, end = window["start_utc"], window["end_utc"]
    first, latest = conn.execute("SELECT min(observed_at), max(observed_at) FROM inventory_snapshots").fetchone()
    retained = conn.execute("SELECT value FROM schema_info WHERE key = 'history_retained_from'").fetchone()
    retained_from = retained[0] if retained else None
    if first is None:
        coverage = "NO_HISTORY"
        note = "No Storage history has been synchronised yet. Nothing is recorded for this date and nothing is assumed."
    elif first >= end:
        coverage = "BEFORE_HISTORY"
        note = (f"Storage history starts at {first} UTC, after this date: nothing was recorded for it "
                "(not \"no change\").")
    elif retained_from is not None and retained_from >= end:
        coverage = "REMOVED"
        note = (f"Local History maintenance removed records before {retained_from} UTC: the observations of this date "
                "are no longer retained and are not reconstructed.")
    elif retained_from is not None and retained_from > start:
        coverage = "PARTLY_REMOVED"
        note = (f"Local History maintenance removed records before {retained_from} UTC: this date is only partly "
                "covered; removed observations are not reconstructed.")
    elif first > start:
        coverage = "STARTS_DURING_DAY"
        note = f"Storage history starts at {first} UTC, during this date: earlier observations do not exist."
    else:
        coverage = "COVERED"
        note = ("Storage history covers this date. Observations exist only when a new Storage version was "
                "synchronised; the file is edited irregularly.")
    stock = current_version(conn, "stock")
    thresholds, raw = [], None
    if stock is not None:
        for sheet in conn.execute("SELECT * FROM stock_sheets WHERE source_version_id = ? ORDER BY sheet_index",
                                  (stock["id"],)).fetchall():
            keys = sheet.keys()
            state = (sheet["threshold_state"] if "threshold_state" in keys else None) or "NOT_CAPTURED"
            thresholds.append(dict(sheet=sheet["sheet_name"], state=state,
                                   column=sheet["threshold_column"] if state == "FOUND" else None,
                                   header=sheet["threshold_header"] if state == "FOUND" else None))
        snap = conn.execute("SELECT * FROM inventory_snapshots WHERE source_version_id = ?", (stock["id"],)).fetchone()
        if snap is not None:
            raw = dict(version_id=stock["id"], rows=snap["record_count"], valid=snap["valid_count"],
                       blank=snap["blank_count"], invalid=snap["invalid_count"],
                       without_usable_id=snap["unkeyed_count"], duplicate_ids=snap["duplicate_key_count"])
    quality = [dict(role=ROLE_NAMES.get(role, role), issue=issue, count=count)
               for (role, issue), count in data_quality_summary(conn).items()]
    return dict(
        history=dict(coverage=coverage, note=note, first_snapshot_utc=first, latest_snapshot_utc=latest,
                     retained_from_utc=retained_from,
                     log_note=("Local History maintenance keeps routine sync logs 90 days and failure logs 180 days; "
                               "alert evaluations are bounded (newest 200 plus provenance). Older records of this "
                               "date may have been removed and are not reconstructed.")),
        thresholds=thresholds, threshold_note=alerts.PENDING_CONFIRMATION, current_storage_raw=raw,
        data_quality=quality,
        not_calculated=[
            dict(field="Actual consumption / material issued", value=None,
                 reason="Not recorded anywhere: " + OBSERVED_NOT_CONSUMPTION + ". Storage differences may include "
                        "receipts, corrections and recounts."),
            dict(field="Total quantity change across materials", value=None,
                 reason="Not added: units are unconfirmed and different materials, Sheets and files are never summed."),
            dict(field="Difference for added / removed / blank / invalid / duplicate changes", value=None,
                 reason="Only two single valid records of the same file have an observed difference."),
        ])


def _sync_notes(sources) -> list[str]:
    """Synchronisation gaps and failures, stated plainly (never filled in)."""
    notes = []
    for role in ("stock", "bom"):
        s = sources[role]
        name, latest = s["role"], s["latest_run"]
        if s["current"] is None:
            notes.append(f"{name} has never been synchronised: no {name} data exists.")
        if latest is not None and latest["outcome"] not in (IMPORTED, UNCHANGED):
            notes.append(f"{name}: the latest check failed ({latest['outcome']} at {latest['finished_utc']} UTC"
                         + (f": {latest['error']}" if latest["error"] else "") + "); stored data are from the last "
                         "successful synchronisation.")
        if not any(s["runs_on_day"].values()):
            notes.append(f"{name} was not checked on this date (no synchronisation record).")
        elif s["failures_on_day_total"]:
            notes.append(f"{name}: {s['failures_on_day_total']} failed or unavailable checks on this date.")
    return notes


# ---------------------------------------------------------------------- generation
def generate(database, report_date: date, session: Session, *, gate: alerts.SessionGate | None = None,
             allow_unverified: bool = False, now: datetime | None = None, tz=None) -> DailySummary:
    """Build one immutable summary. Raises ConfirmationRequired (UNVERIFIED without consent), DailyReadError,
    DailyError. Never writes anything."""
    now = now or utc_now()
    local_now = local_moment(now, tz)
    today = local_now.date()
    if report_date > today:
        raise DailyError(f"{report_date} is in the future; choose today or an earlier date.")
    window = day_window(report_date, tz)
    try:
        with read_view(database) as conn:
            basis = _basis(conn)
            sources = _sources(conn, window, session)
            version_reasons = _version_checks(conn, session)
            alert_state = _alerts(conn)
            evaluations = _evaluations_on_day(conn, window)
            changes = _changes(conn, window)
            limitations = _limitations(conn, window)
    except HistoryReadError as exc:
        raise DailyReadError(f"The local database could not be read; no summary was produced: {exc}") from exc
    historical = report_date != today
    session_reasons = []
    if session.authorization is None:
        session_reasons.append(session.reason or "the Excel files were not both verified in this session")
    elif not session.alert_current:
        session_reasons.append("the alerts were not re-checked in this session" +
                               (f" ({session.reason})" if session.reason else ""))
    if gate is not None and session.generation is not None and not gate.valid(session.generation):
        session_reasons.append("this session's verification changed while the summary was generated")
    if session.generation is None and session.authorization is not None:
        session_reasons.append("no session generation was supplied")
    alerts_current = not session_reasons and not version_reasons and alert_state["match"]
    reasons = []
    if historical:
        reasons.append(f"{report_date} is a past date: the stock and alert state of that day cannot be reconstructed")
    reasons.extend(session_reasons)
    reasons.extend(version_reasons)
    if not alert_state["match"]:
        reasons.append("alerts unavailable: " + alert_state["reason"])
    verified = not reasons
    if not verified and not allow_unverified:
        raise ConfirmationRequired(reasons)

    report_id = uuid.uuid4().hex
    status = VERIFIED if verified else UNVERIFIED
    at_generation = dict(alert_state)
    if alert_state["match"]:
        at_generation["status"] = CURRENT if alerts_current else STORED
        at_generation["label"] = (
            "Re-checked in this session: the alerts of the current files come from a verified evaluation of the "
            "versions this program has just checked." if alerts_current else
            "STORED RESULT, NOT RE-CHECKED IN THIS SESSION: alerts of the last verified evaluation of the current "
            "versions; they may be out of date.")
    else:
        at_generation.update(status=UNAVAILABLE, label="ALERTS UNAVAILABLE — " + alert_state["reason"] +
                             ". This is not a statement that there are no alerts.")
    if historical:
        for_day = dict(available=False, reason=(
            f"The database keeps only the current alert state. The alerts of {report_date} cannot be reconstructed "
            "and are not shown; the alerts below are those at generation time and are NOT the state on that date."))
    else:
        for_day = dict(available=at_generation["status"] == CURRENT,
                       reason=None if at_generation["status"] == CURRENT else at_generation["label"])
    generated_local = local_now.strftime("%Y%m%d_%H%M%S")
    data = dict(
        format=FORMAT, title=TITLE, report_id=report_id, status=status, report_date=report_date.isoformat(),
        historical_date=historical,
        timezone=dict(label=timezone_label(local_now), day_start=timezone_label(datetime.fromisoformat(window["start_local"])),
                      day_end=timezone_label(datetime.fromisoformat(window["end_local"]))),
        window=window,
        generated=dict(utc=stamp(now), local=local_now.isoformat(timespec="seconds")),
        verification=dict(
            status=status, verified=verified, reasons=reasons, confirmed_unverified_by_user=not verified,
            cloud=CLOUD_NOT_VERIFIED,
            session=dict(both_files_verified=session.authorization is not None, alerts_rechecked=session.alert_current,
                         generation=session.generation, reason=session.reason),
            basis=dict(schema=basis[0], stock_version=basis[1], bom_version=basis[2], stock_sync_run=basis[3],
                       bom_sync_run=basis[4], alert_evaluation=basis[5])),
        sources=sources,
        alerts=dict(rules=("M3.2C rules from synchronised data: OUT_OF_STOCK = recorded 0 (not a proven order "
                           "shortage); LOW_STOCK is a trial (LIVE STOCK < threshold of the same row); not in stock "
                           "master = unknown, not 0; blank ≠ 0; duplicates never added."),
                    not_normal=NOT_STOCK_NORMAL, sum_note=SUM_NOTE, for_report_date=for_day,
                    at_generation=at_generation, evaluations_on_date=evaluations,
                    evaluations_note=("Alert evaluations recorded on this date (counts as recorded by each evaluation; "
                                      "item lists of past evaluations are not retained).")),
        changes=dict(changes, no_record_note=NO_RECORD_NOTE if changes["total"] == 0 else None,
                     source_switches=[dict(role=ROLE_NAMES[role], **v) for role in ("stock", "bom")
                                      for v in sources[role]["imported_on_day"] if v["source_switched"]],
                     attribution=("Changes belong to the date on which this program observed them (snapshot time), "
                                  "not to the file's modified time and not to an actual business date.")),
        limitations=dict(limitations, sync_notes=_sync_notes(sources)))
    text = json.dumps(data, ensure_ascii=False, indent=1, sort_keys=False, default=str)
    return DailySummary(report_id, report_date.isoformat(), verified, session.generation, basis, generated_local, text)


# ---------------------------------------------------------------------- rendering (from the one JSON text)
def _e(value) -> str:
    return html.escape("—" if value is None or value == "" else str(value), quote=True)


def _table(headers, rows) -> str:
    head = "".join(f"<th>{_e(h)}</th>" for h in headers)
    body = "".join("<tr>" + "".join(f"<td>{_e(c)}</td>" for c in row) + "</tr>" for row in rows)
    if not rows:
        body = f'<tr><td colspan="{len(headers)}" class="muted">None recorded.</td></tr>'
    return f"<table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table>"


CSS = """
body{font-family:"Segoe UI",Arial,sans-serif;color:#243244;background:#fff;margin:24px;font-size:13px;line-height:1.45}
h1{font-size:22px;margin:0 0 4px}h2{font-size:16px;margin:22px 0 6px;border-bottom:1px solid #ccd5df;padding-bottom:3px}
h3{font-size:14px;margin:14px 0 4px}.muted{color:#687789}.banner{padding:8px 12px;margin:8px 0;font-weight:bold}
.unverified{background:#fde9e7;color:#8a0016;border:2px solid #b00020}.verified{background:#e8f3ee;color:#24543f;
border:1px solid #3b715e}.note{background:#fff4d6;border:1px solid #e3c66f;padding:6px 10px;margin:6px 0}
table{border-collapse:collapse;width:100%;margin:6px 0 10px;font-size:12px}th,td{border:1px solid #d5dde6;
padding:3px 6px;text-align:left;vertical-align:top;word-break:break-word}th{background:#eaf0f5}
dl{display:grid;grid-template-columns:max-content 1fr;gap:2px 12px;margin:4px 0}dt{font-weight:bold}dd{margin:0}
footer{margin-top:24px;font-size:11px;color:#687789}@media print{body{margin:10mm}.banner{border-width:1px}
tr{page-break-inside:avoid}}
"""


def _dl(pairs) -> str:
    return "<dl>" + "".join(f"<dt>{_e(k)}</dt><dd>{_e(v)}</dd>" for k, v in pairs) + "</dl>"


def _version_text(v) -> str:
    if not v:
        return "—"
    return (f"v{v['id']} · {v['file_name']} · imported {v['imported_utc']} UTC · file modified "
            f"{v['source_modified_utc']} UTC · {v['path']}")


def render_html(summary: DailySummary) -> str:
    d = summary.data()
    unverified = d["status"] != VERIFIED
    title = f"{TITLE} {d['report_date']}" + (" — UNVERIFIED" if unverified else "")
    v, a, c, lim = d["verification"], d["alerts"], d["changes"], d["limitations"]
    parts = [f"<h1>{_e(title)}</h1>"]
    if unverified:
        parts.append('<div class="banner unverified">UNVERIFIED REPORT — generated after explicit confirmation. '
                     f"{_e('; '.join(v['reasons']))}. {_e(CLOUD_NOT_VERIFIED)}.</div>")
    else:
        parts.append('<div class="banner verified">Local Sources Verified in this session at generation time · '
                     f"{_e(CLOUD_NOT_VERIFIED)}</div>")
    parts.append(f'<div class="note">{_e(CLOUD_NOT_VERIFIED)}: the Google Drive cloud copy is never checked. '
                 f'{_e(OBSERVED_NOT_CONSUMPTION)}.</div>')
    # 1. report information
    parts.append("<h2>1. Report information</h2>")
    parts.append(_dl([("Report date", d["report_date"] + (" (past date)" if d["historical_date"] else " (today)")),
                      ("Time zone", d["timezone"]["label"]),
                      ("Day window", f"{d['window']['start_local']} to {d['window']['end_local']} (exclusive) · UTC "
                                     f"{d['window']['start_utc']} to {d['window']['end_utc']} · {d['window']['rule']}"),
                      ("Generated", f"{d['generated']['local']} · UTC {d['generated']['utc']}"),
                      ("Status", v["status"]), ("Report ID", d["report_id"]),
                      ("Verified in this session", "Yes" if v["verified"] else "No — " + "; ".join(v["reasons"])),
                      ("Database basis", ", ".join(f"{k} {val}" for k, val in v["basis"].items()))]))
    rows = []
    for role in ("stock", "bom"):
        s = d["sources"][role]
        run = s["latest_run"] or {}
        success = s["last_success"] or {}
        verified_by = s["session_verified"]
        rows.append((s["role"], _version_text(s["current"]),
                     _version_text(s["in_effect_at_day_end"]) if d["historical_date"] else "(today)",
                     f"{run.get('outcome', '—')} at {run.get('finished_utc', '—')} UTC" + (
                         f" · {run['error']}" if run.get("error") else ""),
                     f"{success.get('finished_utc', '—')} UTC", s["freshness_state"],
                     f"v{verified_by['version_id']} · {verified_by['path']}" if verified_by else "not in this session",
                     ", ".join(f"{k} {n}" for k, n in s["runs_on_day"].items())))
    parts.append(_table(("Source", "Current version (at generation)", "Version in effect at end of report date",
                         "Latest check", "Last verified", "Status", "Verified in this session", "Checks on this date"),
                        rows))
    # 2. alerts
    g = a["at_generation"]
    parts.append("<h2>2. Stock alerts</h2>")
    parts.append(f'<p class="muted">{_e(a["rules"])}</p><div class="note">{_e(a["not_normal"])}</div>')
    if not a["for_report_date"]["available"]:
        parts.append(f'<div class="banner unverified">Alerts for {_e(d["report_date"])}: NOT AVAILABLE — '
                     f'{_e(a["for_report_date"]["reason"])}</div>')
    heading = ("Alerts at generation time" + (f" ({d['generated']['local']}) — not the state on {d['report_date']}"
                                              if d["historical_date"] else ""))
    parts.append(f"<h3>{_e(heading)}</h3><p><b>{_e(g['status'])}</b> — {_e(g['label'])}</p>")
    if g["status"] != UNAVAILABLE:
        sc = g["scope"]
        parts.append(_dl([("Basis", f"evaluation #{sc['evaluation_id']} at {sc['evaluated_utc']} UTC"),
                          ("Storage", f"v{sc['storage_version']} · {sc['storage_file']}"),
                          ("BOM", f"v{sc['bom_version']} · {sc['bom_file']}"),
                          ("Storage Sheets", ", ".join(sc["sheets"]) or "—")]))
        parts.append(_table(("Alert type", "Alerts", "Distinct Material IDs", "Entries without Material ID",
                             "Storage Sheets", "Issues"),
                            [(t["type"], t["alerts"], t["distinct_material_ids"], t["entries_without_material_id"],
                              t["storage_sheets"], ", ".join(f"{k} {n}" for k, n in t["subtypes"].items()))
                             for t in g["by_type"]]))
        parts.append(f"<p>Distinct Material IDs with any alert: <b>{_e(g['distinct_material_ids_any_type'])}</b>. "
                     f"{_e(a['sum_note'])}</p>")
        if g["total"] == 0:
            parts.append("<p>No alert of these types in this evaluation. This is not a statement that stock is "
                         "sufficient.</p>")
        parts.append(_table(("Type", "Issue", "Material ID", "Description", "Storage Sheet", "Row(s)",
                             "LIVE STOCK (raw)", "Threshold (raw)", "Shortfall (trial)", "First seen UTC", "Note"),
                            [(i["type"], i["issue"], i["material_id"] or i.get("code"), i["description"], i["sheet"],
                              ", ".join(str(x) for x in i["rows"]) if i["rows"] else
                              (f"BOM {i.get('bom_rows')} rows / {len(i.get('products', []))} products"
                               if i.get("bom_rows") is not None else "—"),
                              i["stock"], i["threshold"], i["shortfall"], i["first_seen_utc"], i["note"])
                             for i in g["items"]]))
        if g["truncated"]:
            parts.append(f"<p class='note'>Only {len(g['items'])} of {g['total']} alerts are listed.</p>")
    if g.get("other_source_active"):
        parts.append(f"<p class='muted'>{_e(g['other_source_active'])} active alerts belong to other source files: "
                     "not re-checked, not recovered, not included above.</p>")
    parts.append(f"<h3>Alert evaluations recorded on {_e(d['report_date'])}</h3><p class='muted'>"
                 f"{_e(a['evaluations_note'])}</p>")
    parts.append(_table(("#", "Finished UTC", "Outcome", "Trigger", "Storage / BOM version", "Recorded counts",
                         "Reason"),
                        [(e["id"], e["finished_utc"], e["outcome"], e["trigger"],
                          f"v{e['stock_version_id']} / v{e['bom_version_id']}",
                          ", ".join(f"{k} {n}" for k, n in (e["counts_by_type"] or {}).items()) or "—", e["reason"])
                         for e in a["evaluations_on_date"]]))
    # 3. observed changes
    parts.append(f"<h2>3. Observed changes on {_e(d['report_date'])}</h2>")
    parts.append(f'<div class="note"><b>{_e(c["caveat"])}</b>. {_e(c["detail"])} {_e(c["attribution"])}</div>')
    parts.append(_table(("Change type", "Changes", "Distinct Material IDs"),
                        [(k, n["changes"], n["distinct_material_ids"]) for k, n in c["by_type"].items()]))
    parts.append(f"<p>Total observed changes: <b>{_e(c['total'])}</b> · distinct Material IDs: "
                 f"<b>{_e(c['distinct_material_ids'])}</b></p>")
    if c["no_record_note"]:
        parts.append(f'<div class="note">{_e(c["no_record_note"])}</div>')
    if c["source_switches"]:
        parts.append(_table(("Source", "Imported UTC", "From", "To"),
                            [(s["role"], s["imported_utc"], s["previous_path"], s["path"]) for s in c["source_switches"]]))
    parts.append(_table(("Snapshot UTC", "Storage version", "File", "Baseline", "Source switched", "Recorded counts"),
                        [(s["observed_utc"], s["version_id"], s["file"], "yes" if s["baseline"] else "no",
                          "yes" if s["source_switched"] else "no", ", ".join(f"{k} {n}" for k, n in s["counts"].items()))
                         for s in c["snapshots"]]))
    parts.append(_table(("Observed UTC", "Sheet", "Material ID", "Change", "Before UTC", "Before", "After",
                         "Observed difference", "Note"),
                        [(i["observed_utc"], i["sheet"], i["material_id"], i["change_type"], i["before_utc"],
                          i["before"], i["after"], i["observed_difference"] or ("— " + (i["difference_reason"] or "")),
                          i["note"]) for i in c["items"]]))
    if c["truncated"]:
        parts.append(f"<p class='note'>Only {len(c['items'])} of {c['total']} observed changes are listed.</p>")
    # 4. limitations
    h = lim["history"]
    parts.append("<h2>4. Data limitations</h2>")
    parts.append(_dl([("History coverage", f"{h['coverage']} — {h['note']}"),
                      ("First / latest snapshot", f"{h['first_snapshot_utc'] or '—'} / {h['latest_snapshot_utc'] or '—'} UTC"),
                      ("Retained from", h["retained_from_utc"] or "no maintenance cleanup recorded"),
                      ("Logs", h["log_note"])]))
    sync_rows = []
    for role in ("stock", "bom"):
        s = d["sources"][role]
        for f in s["failures_on_day"]:
            sync_rows.append((s["role"], f["finished_utc"], f["outcome"], f["path"], f["error"]))
    parts.append("<h3>Synchronisation on this date</h3>")
    parts.extend(f"<p>{_e(n)}</p>" for n in lim["sync_notes"])
    parts.append(_table(("Source", "Finished UTC", "Outcome", "File", "Error"), sync_rows))
    parts.append("<h3>Thresholds (current Storage version)</h3>")
    parts.append(f"<p class='muted'>{_e(lim['threshold_note'])}</p>")
    parts.append(_table(("Storage Sheet", "Threshold column state", "Column", "Header"),
                        [(t["sheet"], t["state"], t["column"], t["header"]) for t in lim["thresholds"]]))
    raw = lim["current_storage_raw"]
    parts.append("<h3>Raw Storage data (current version)</h3>")
    parts.append(_dl([("Rows", raw["rows"]), ("Valid stock", raw["valid"]), ("Blank stock (not 0)", raw["blank"]),
                      ("Invalid / text stock (not converted)", raw["invalid"]),
                      ("Rows without a usable Material ID", raw["without_usable_id"]),
                      ("Duplicate Material IDs (rows kept separate)", raw["duplicate_ids"])])
                 if raw else "<p class='muted'>Not available: no synchronised Storage snapshot.</p>")
    parts.append(_table(("Source", "Data quality issue", "Count"),
                        [(q["role"], q["issue"], q["count"]) for q in lim["data_quality"]]))
    parts.append("<h3>Not calculated</h3>")
    parts.append(_table(("Field", "Value", "Reason"),
                        [(n["field"], "not calculated (not 0)", n["reason"]) for n in lim["not_calculated"]]))
    parts.append(f"<footer>Report ID {_e(d['report_id'])} · {_e(d['format'])} · data SHA-256 {_e(summary.digest)} · "
                 f"{_e(v['status'])} · {_e(CLOUD_NOT_VERIFIED)} · Generated by Material Requirement &amp; Stock "
                 "Checker (M3.2D). Read-only: Excel, stock and Drive settings were not changed.</footer>")
    return ("<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">"
            f"<meta name=\"report-id\" content=\"{_e(d['report_id'])}\">"
            f"<meta name=\"data-sha256\" content=\"{_e(summary.digest)}\">"
            f"<title>{_e(title)}</title><style>{CSS}</style></head><body>\n" + "\n".join(parts) + "\n</body></html>\n")


def render_text(summary: DailySummary, limit: int = PREVIEW_ITEMS) -> str:
    """Plain-text preview of the same data (lists shortened; the saved files contain every loaded row)."""
    d = summary.data()
    v, a, c, lim = d["verification"], d["alerts"], d["changes"], d["limitations"]
    g = a["at_generation"]
    lines = [f"{TITLE} {d['report_date']}" + (" — UNVERIFIED" if d["status"] != VERIFIED else " — VERIFIED") +
             f" · {CLOUD_NOT_VERIFIED}"]
    if d["status"] != VERIFIED:
        lines.append("UNVERIFIED: " + "; ".join(v["reasons"]))
    lines += [f"Time zone {d['timezone']['label']} · day {d['window']['start_local']} → {d['window']['end_local']} "
              f"(exclusive) · generated {d['generated']['local']} · report ID {d['report_id']}", "",
              "1. SOURCES"]
    for role in ("stock", "bom"):
        s = d["sources"][role]
        run = s["latest_run"] or {}
        lines.append(f"  {s['role']}: {_version_text(s['current'])}")
        lines.append(f"    latest check {run.get('outcome', '—')} at {run.get('finished_utc', '—')} UTC · "
                     f"{s['freshness_state']} · this session: "
                     f"{'v' + str(s['session_verified']['version_id']) if s['session_verified'] else 'not verified'}"
                     f" · checks on this date: " + ", ".join(f"{k} {n}" for k, n in s["runs_on_day"].items()))
        if d["historical_date"]:
            lines.append(f"    in effect at end of {d['report_date']}: {_version_text(s['in_effect_at_day_end'])}")
    lines += ["", "2. STOCK ALERTS", "  " + a["not_normal"]]
    if not a["for_report_date"]["available"]:
        lines.append(f"  Alerts for {d['report_date']}: NOT AVAILABLE — {a['for_report_date']['reason']}")
    lines.append(f"  At generation time: {g['status']} — {g['label']}")
    if g["status"] != UNAVAILABLE:
        for t in g["by_type"]:
            lines.append(f"    {t['type']}: {t['alerts']} alerts · {t['distinct_material_ids']} distinct Material IDs"
                         + (f" · {t['entries_without_material_id']} without ID" if t["entries_without_material_id"] else "")
                         + (" · " + ", ".join(f"{k} {n}" for k, n in t["subtypes"].items()) if t["subtypes"] else ""))
        lines.append(f"    Distinct Material IDs with any alert: {g['distinct_material_ids_any_type']}. {a['sum_note']}")
        if g["total"] == 0:
            lines.append("    No alert of these types in this evaluation. This is not a statement that stock is "
                         "sufficient.")
        for i in g["items"][:limit]:
            lines.append(f"    - {i['type']}{' / ' + i['issue'] if i['issue'] else ''} · {i['material_id'] or i.get('code', '—')}"
                         f" · Sheet {i['sheet']} · stock {i['stock']} · threshold {i['threshold']}")
        if len(g["items"]) > limit:
            lines.append(f"    … {len(g['items']) - limit} more in the saved report")
    lines.append(f"  Evaluations recorded on this date: {len(a['evaluations_on_date'])}")
    lines += ["", f"3. OBSERVED CHANGES ON {d['report_date']} — {c['caveat']}", "  " + c["attribution"]]
    lines.append("  " + " · ".join(f"{k} {n['changes']} ({n['distinct_material_ids']} IDs)" for k, n in c["by_type"].items()))
    lines.append(f"  Total {c['total']} · distinct Material IDs {c['distinct_material_ids']} · Storage snapshots "
                 f"{len(c['snapshots'])} · source switches {len(c['source_switches'])}")
    if c["no_record_note"]:
        lines.append("  " + c["no_record_note"])
    for i in c["items"][:limit]:
        lines.append(f"    - {i['observed_utc']} UTC · {i['sheet']} · {i['material_id']} · {i['change_type']} · "
                     f"{i['before']} → {i['after']} · difference {i['observed_difference'] or '— ' + (i['difference_reason'] or '')}")
    if len(c["items"]) > limit:
        lines.append(f"    … {len(c['items']) - limit} more in the saved report")
    h = lim["history"]
    lines += ["", "4. DATA LIMITATIONS", f"  History: {h['coverage']} — {h['note']}", "  " + h["log_note"]]
    lines.extend("  " + n for n in lim["sync_notes"])
    for t in lim["thresholds"]:
        lines.append(f"  Threshold, Sheet {t['sheet']}: {t['state']}" + (f" ({t['column']} '{t['header']}')" if t["column"] else ""))
    lines.append("  " + lim["threshold_note"])
    raw = lim["current_storage_raw"]
    if raw:
        lines.append(f"  Current Storage v{raw['version_id']}: {raw['rows']} rows · blank {raw['blank']} (not 0) · "
                     f"invalid {raw['invalid']} (not converted) · without usable ID {raw['without_usable_id']} · "
                     f"duplicate IDs {raw['duplicate_ids']}")
    for n in lim["not_calculated"]:
        lines.append(f"  Not calculated — {n['field']}: {n['reason']}")
    return "\n".join(lines)


# ---------------------------------------------------------------------- saving
def file_stem(summary: DailySummary) -> str:
    prefix = "" if summary.verified else "UNVERIFIED_"
    return f"{prefix}Daily_Stock_Summary_{summary.report_date}_generated_{summary.generated_local}"


SUPPORTED_JOURNAL_MODES = ("delete", "truncate", "persist")  # rollback journals: a held read lock blocks COMMIT
STAGING_PREFIX = ".mrc-daily-"
STAGING_SUFFIX = ".partial"


def _checkpoint(stage: str) -> None:
    """No-op test hook of save(): 'staged' (both files written and verified), 'before_publish' (database read lock
    and session guard held, basis just confirmed), 'retry' (after a lost name race, no lock held)."""


def _write_verified(path: Path, payload: bytes) -> None:
    with open(path, "xb") as stream:  # a new file inside our own private staging directory
        stream.write(payload)
        stream.flush()
        os.fsync(stream.fileno())
    if path.read_bytes() != payload:
        raise DailyError(f"The staged file could not be verified: {path}")


def _publish(staging: Path, target: Path) -> None:
    """The commit point: ONE rename of the complete staging directory to its final name. On Windows the rename
    refuses an existing destination (FileExistsError); on other systems an existing non-empty directory refuses."""
    os.rename(staging, target)


@contextmanager
def _publication_basis(database):
    """The current database basis, read inside a read transaction that stays open while the caller publishes. Only
    with a rollback journal does that open read lock stop any other connection or program from committing, so the
    basis cannot change between this check and the rename. Any other journal mode (WAL, where readers never block
    commits, or memory/off) is refused inside the same transaction; the mode is never changed here."""
    try:
        with read_view(database) as conn:
            mode = str(conn.execute("PRAGMA journal_mode").fetchone()[0]).lower()
            if mode not in SUPPORTED_JOURNAL_MODES:
                raise DailyUnsupported(
                    f"Saving the Daily Stock Summary needs a rollback-journal database (journal_mode DELETE, TRUNCATE "
                    f"or PERSIST); this database uses {mode.upper()}, where a final check cannot stop another program "
                    "from committing before the report is published. Nothing was saved and the database was not "
                    "changed. The summary can still be generated and previewed.")
            yield _basis(conn)
    except HistoryReadError as exc:
        raise DailyReadError(f"The local database could not be read; nothing was saved: {exc}") from exc


@dataclass(frozen=True)
class Saved:
    folder: Path   # the report directory: it exists only complete (both files), never partly
    html: Path
    json: Path


def save(summary: DailySummary, folder, database, *, gate: alerts.SessionGate | None = None) -> Saved:
    """Publish the HTML and JSON of one summary as a NEW report directory `<stem>[ (n)]` inside `folder`.

    Contract: both files are written and read back inside a private staging directory `.mrc-daily-….partial`; the
    report becomes visible only by one rename of that directory. Immediately before the rename, while a database
    read transaction is held (SQLite lock first, then this session's publication guard - the M3.2C order), the
    journal mode must be a rollback journal (else DailyUnsupported), the database basis must still equal the
    summary's basis and a VERIFIED summary's session generation must still be current; otherwise DailyStale and
    nothing is published. Every name-race retry checks again. Nothing existing is
    replaced. On failure the original exception is raised; a staging directory that could not be removed is named on
    the exception (`cleanup_warning`, `leftover`) and is recognisable by its `.partial` name."""
    folder = Path(folder)
    if not folder.is_dir():
        raise DailyError(f"The folder does not exist: {folder}")
    if read_basis(database) != summary.basis:  # early, cheap refusal; the authoritative check is at publication
        raise DailyStale(STALE_DATA)
    if summary.verified and gate is not None and not gate.valid(summary.generation):
        raise DailyStale(STALE_SESSION)
    stem = file_stem(summary)
    payloads = ((".json", summary.json_text.encode("utf-8")), (".html", render_html(summary).encode("utf-8")))
    staging = folder / f"{STAGING_PREFIX}{summary.report_id[:12]}-{uuid.uuid4().hex[:8]}{STAGING_SUFFIX}"
    failure = None
    try:
        staging.mkdir()
        for suffix, payload in payloads:
            _write_verified(staging / (stem + suffix), payload)
        _checkpoint("staged")
        for n in range(1, 100):
            target = folder / (stem if n == 1 else f"{stem} ({n})")
            if os.path.lexists(target):
                continue
            published = collided = False
            error = None
            with _publication_basis(database) as basis:
                if basis != summary.basis:
                    raise DailyStale(STALE_DATA)
                guard = (gate.publishing(summary.generation) if summary.verified and gate is not None
                         else nullcontext(True))
                with guard as current:
                    if not current:
                        raise DailyStale(STALE_SESSION)
                    _checkpoint("before_publish")
                    try:
                        _publish(staging, target)
                        published = True
                    except FileExistsError:
                        collided = True
                    except OSError as exc:  # raised after the read transaction ends (read_view converts OSError)
                        error = exc
            if error is not None:
                raise error
            if published:
                return Saved(target, target / (stem + ".html"), target / (stem + ".json"))
            if collided:
                _checkpoint("retry")
        raise DailyError("No free report name was found; nothing was saved.")
    except BaseException as exc:
        failure = exc
        raise
    finally:
        if staging.exists():
            try:
                shutil.rmtree(staging)
            except OSError as cleanup:
                warning = (f"Incomplete staging directory could not be removed: {staging} ({cleanup}). It is not a "
                           "report; delete it manually.")
                if failure is not None:
                    failure.cleanup_warning = warning  # the original error stays the raised error
                    failure.leftover = staging
                    failure.add_note(warning)


STALE_DATA = ("The synchronised data changed after this summary was generated (new version, sync record or alert "
              "evaluation). Generate it again; nothing was saved.")
STALE_SESSION = ("This session's verification changed after the summary was generated. Generate it again; nothing "
                 "was saved.")


# ---------------------------------------------------------------------- bounded background runner (no Tk)
class DailyRunner:
    """At most one task runs and at most one waits (a newer request replaces the waiting one). Results are delivered
    as (request_id, kind, result, error) on `events`; nothing is delivered after close()."""

    def __init__(self):
        self.events = queue.Queue()
        self._lock = threading.Lock()
        self.running = False
        self.pending = None
        self.closed = False
        self.threads_started = 0

    def request(self, request_id, kind, action) -> str:
        with self._lock:
            if self.closed:
                return "closed"
            if self.running:
                self.pending = (request_id, kind, action)
                return "queued"
            self.running = True
            self.threads_started += 1
        threading.Thread(target=self._work, args=(request_id, kind, action), daemon=True, name="m32d-daily").start()
        return "started"

    @property
    def busy(self) -> bool:
        with self._lock:
            return self.running or self.pending is not None

    def close(self):
        with self._lock:
            self.closed = True
            self.pending = None

    def _work(self, request_id, kind, action):
        while True:
            try:
                result, error = action(), None
            except Exception as exc:
                result, error = None, exc
            with self._lock:
                if not self.closed:
                    self.events.put((request_id, kind, result, error))
                if self.closed or self.pending is None:
                    self.running = False
                    return
                request_id, kind, action = self.pending
                self.pending = None
